{"cmd":"docker compose exec app node -e '
const http = require("http");
http.get("http://127.0.0.1:9229/json", res => {
  let b = "";
  res.on("data", c => b += c);
  res.on("end", () => {
    const info = JSON.parse(b)[0];
    const req = http.request({
      host: "127.0.0.1",
      port: 9229,
      path: "/" + info.id,
      headers: {
        Connection: "Upgrade",
        Upgrade: "websocket",
        "Sec-WebSocket-Version": 13,
        "Sec-WebSocket-Key": Buffer.from("dGhlIHNhbXBsZSBub25jZQ==").toString("base64")
      }
    });
    req.on("upgrade", (res, socket) => {
      let state = 0;
      function send(obj) {
        const payload = Buffer.from(JSON.stringify(obj));
        const len = payload.length;
        let header;
        if (len < 126) header = Buffer.from([0x81, 0x80 | len, 0, 0, 0, 0]);
        else {
          header = Buffer.alloc(8);
          header[0] = 0x81;
          header[1] = 0x80 | 126;
          header.writeUInt16BE(len, 2);
        }
        socket.write(Buffer.concat([header, payload]));
      }
      send({ id: 1, method: "Runtime.evaluate", params: { expression: "process.mainModule.require(\"./services/statements\").statementFor" } });
      let dataBuf = Buffer.alloc(0);
      socket.on("data", chunk => {
        dataBuf = Buffer.concat([dataBuf, chunk]);
        while (dataBuf.length > 2) {
          const len = dataBuf[1] & 0x7f;
          let offset = 2;
          let payloadLen = len;
          if (len === 126) {
            payloadLen = dataBuf.readUInt16BE(2);
            offset = 4;
          }
          if (dataBuf.length < offset + payloadLen) break;
          const msg = JSON.parse(dataBuf.slice(offset, offset + payloadLen).toString());
          dataBuf = dataBuf.slice(offset + payloadLen);
          if (msg.id === 1) {
            send({ id: 2, method: "Runtime.getProperties", params: { objectId: msg.result.result.objectId } });
          } else if (msg.id === 2) {
            const scopes = msg.result.internalProperties.find(p => p.name === "[[Scopes]]");
            send({ id: 3, method: "Runtime.getProperties", params: { objectId: scopes.value.objectId } });
          } else if (msg.id === 3) {
            const closure = msg.result.result[0];
            send({ id: 4, method: "Runtime.getProperties", params: { objectId: closure.value.objectId } });
          } else if (msg.id === 4) {
            console.log(JSON.stringify(msg.result.result.map(p => ({ name: p.name, val: p.value ? p.value.description : undefined }))));
            const cacheProp = msg.result.result.find(p => p.name === "cache");
            if (cacheProp) {
              send({ id: 5, method: "Runtime.getProperties", params: { objectId: cacheProp.value.objectId } });
            }
          } else if (msg.id === 5) {
            console.log("Cache property count:", msg.result.result.length);
            console.log("Sample cache keys:", msg.result.result.slice(0, 10).map(p => p.name));
            process.exit(0);
          }
        }
      });
    });
    req.end();
  });
});
'"}

