    );
    await payments.charge(orderId, amountCents);
    await client.query(\"UPDATE orders SET status = \\\\x27paid\\\\x27 WHERE id = "'$1", [orderId]);
    await client.query("COMMIT");
  } catch (err) {
    try {
      await client.query("ROLLBACK");
    } catch (_) {}
    throw err;
  } finally {
    client.release();
  }
}

module.exports = { placeOrder };
