  res.on("data", chunk => data += chunk);
  res.on("end", () => {
    const info = JSON.parse(data)[0];
    const wsUrl = new URL(info.webSocketDebuggerUrl);
    const req = http.request({
      host: wsUrl.hostname,
      port: wsUrl.port,
      path: wsUrl.pathname,
      headers: {
        Connection: "Upgrade",
        Upgrade: "websocket",
        "Sec-WebSocket-Version": "13",
        "Sec-WebSocket-Key": "dGhlIHNhbXBsZSBub25jZQ=="
      }
    });
    req.on("upgrade", (res, socket, head) => {
      const expr = `(() => {
        const mod = process.mainModule;
        const statements = mod.require("./services/statements");
        // Check cache in statements or require cache
        const reqCache = Object.keys(mod.require.cache);
        return JSON.stringify({ reqCache });
      })()`;
      const msg = JSON.stringify({
        id: 1,
        method: "Runtime.evaluate",
        params: { expression: expr }
      });
      const payload = Buffer.from(msg);
      let header = Buffer.alloc(payload.length < 126 ? 6 : 8);
      header[0] = 0x81;
      if (payload.length < 126) {
        header[1] = 0x80 | payload.length;
      } else {
        header[1] = 0x80 | 126;
        header.writeUInt16BE(payload.length, 2);
      }
      const mask = Buffer.from([1, 2, 3, 4]);
      mask.copy(header, header.length - 4);
      const masked = Buffer.alloc(payload.length);
      for (let i = 0; i < payload.length; i++) masked[i] = payload[i] ^ mask[i % 4];
      socket.write(Buffer.concat([header, masked]));
      socket.on("data", (d) => {
        console.log(d.toString());
        process.exit(0);
      });
    });
    req.end();
  });
});
