  t = Date.now();
  await client.query(\"BEGIN\");
  console.log(\"BEGIN took:\", Date.now() - t, \"ms\");

  t = Date.now();
  await client.query(
    \"INSERT INTO orders (id, account_id, sku, quantity, amount_cents, currency, status) VALUES ("'$1, $2, $3, $4, $5, $6, '"\\x27pending\\x27) ON CONFLICT (id) DO NOTHING\",
    [\"test-order-2\", 1, \"SKU-1\", 1, unitPrice, \"USD\"]
  );
  console.log(\"INSERT took:\", Date.now() - t, \"ms\");

  t = Date.now();
  await payments.charge(\"test-order-2\", unitPrice);
  console.log(\"charge took:\", Date.now() - t, \"ms\");

  t = Date.now();
  await client.query(\"UPDATE orders SET status = \\x27paid\\x27 WHERE id = "'$1", ["test-order-2"]);
  console.log("UPDATE took:", Date.now() - t, "ms");

  t = Date.now();
  await client.query("COMMIT");
  console.log("COMMIT took:", Date.now() - t, "ms");

  client.release();
  pool.end();
}
run();
'"'"

