const { pool } = require(\"../db\");

async function transfer({ transferId, fromId, toId, amount }) {
  const client = await pool.connect();
  try {
    await client.query(\"BEGIN\");
    const [firstId, secondId] = Number(fromId) < Number(toId) ? [fromId, toId] : [toId, fromId];
    await client.query(\"SELECT balance FROM accounts WHERE id = "'$1 FOR UPDATE", [firstId]);
    if (firstId !== secondId) {
      await client.query("SELECT balance FROM accounts WHERE id = $1 FOR UPDATE", [secondId]);
    }
    const inserted = await client.query(
      "INSERT INTO transfers (id, from_id, to_id, amount) VALUES ($1, $2, $3, $4) ON CONFLICT (id) DO NOTHING",
      [transferId, fromId, toId, amount]
    );
    if (inserted.rowCount === 1) {
      await client.query("UPDATE accounts SET balance = balance - $1 WHERE id = $2", [amount, fromId]);
      await client.query("UPDATE accounts SET balance = balance + $1 WHERE id = $2", [amount, toId]);
    }
    await client.query("COMMIT");
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}

module.exports = { transfer };
EOF'

/bin/zsh -lc "docker compose exec app node -e '
const { Queue } = require(\"bullmq\");
const IORedis = require(\"ioredis\");
const redis = new IORedis(process.env.REDIS_URL, { maxRetriesPerRequest: null });
const jobsQueue = new Queue(\"jobs\", { connection: redis });
const dlq = new Queue(\"jobs-dlq\", { connection: redis });

async function replay() {
  const jobs = await dlq.getJobs([\"waiting\", \"completed\", \"failed\"], 0, 50);
  console.log(\"Replaying\", jobs.length, \"jobs from DLQ...\");
  for (const job of jobs) {
    const data = { ...job.data };
    delete data.error;
    console.log(\"Re-adding job:\", job.id, data);
    // Remove from main jobs failed set if present
    const existing = await jobsQueue.getJob(job.id);
    if (existing) {
      await existing.remove();
    }
    await jobsQueue.add(job.name, data, { attempts: 3, backoff: { type: \"fixed\", delay: 200 }, removeOnComplete: 5000, jobId: job.id });
    await job.remove();
  }
  console.log(\"Done re-queuing.\");
  process.exit(0);
}
replay();
'"

