/bin/zsh -lc "cat << 'EOF' > src/logger.js
const fs = require(\"fs\");
const path = require(\"path\");
const config = require(\"./config\");

const LEVELS = { debug: 10, info: 20, warn: 30, error: 40 };
const threshold = LEVELS[config.logLevel] || LEVELS.info;
const LOG_FILE = path.join(config.logDir, \"app.log\");
const BACKUP_LOG_FILE = path.join(config.logDir, \"app.log.1\");
const MAX_LOG_SIZE = 64 * 1024; // 64 KB

try {
  fs.mkdirSync(config.logDir, { recursive: true });
} catch (_) {}

function rotate() {
  try {
    if (fs.existsSync(BACKUP_LOG_FILE)) {
      fs.unlinkSync(BACKUP_LOG_FILE);
    }
  } catch (_) {}
  try {
    if (fs.existsSync(LOG_FILE)) {
      const stat = fs.statSync(LOG_FILE);
      if (stat.size > MAX_LOG_SIZE) {
        fs.truncateSync(LOG_FILE, 0);
      } else {
        fs.renameSync(LOG_FILE, BACKUP_LOG_FILE);
      }
    }
  } catch (_) {}
}

function writeToFile(line) {
  try {
    let stat;
    try {
      stat = fs.statSync(LOG_FILE);
    } catch (e) {
      if (e.code "'!== "ENOENT") throw e;
    }
    if (stat && stat.size >= MAX_LOG_SIZE) {
      rotate();
    }
    fs.appendFileSync(LOG_FILE, line);
  } catch (err) {
    try {
      try {
        if (fs.existsSync(BACKUP_LOG_FILE)) fs.unlinkSync(BACKUP_LOG_FILE);
      } catch (_) {}
      try {
        fs.truncateSync(LOG_FILE, 0);
      } catch (_) {}
      fs.appendFileSync(LOG_FILE, line);
    } catch (_) {
      // Never crash the application due to logging errors
    }
  }
}

function write(level, msg, fields = {}) {
  if (LEVELS[level] < threshold) return;
  const line = JSON.stringify({ ts: new Date().toISOString(), level, msg, ...fields }) + "'"\\n\";
  if (level "'!== "debug") {
    try {
      process.stdout.write(line);
    } catch (_) {}
  }
  writeToFile(line);
}

module.exports = {
  debug: (msg, fields) => write("debug", msg, fields),
  info: (msg, fields) => write("info", msg, fields),
  warn: (msg, fields) => write("warn", msg, fields),
  error: (msg, fields) => write("error", msg, fields),
};
EOF'

