const threshold = LEVELS[config.logLevel] || LEVELS.info;
const LOG_FILE = path.join(config.logDir, "app.log");
const BACKUP_LOG_FILE = path.join(config.logDir, "app.log.1");
const MAX_LOG_SIZE = 64 * 1024; // 64 KB

try {
  fs.mkdirSync(config.logDir, { recursive: true });
} catch (_) {}

function rotate() {
  try {
    if (fs.existsSync(BACKUP_LOG_FILE)) {
      fs.unlinkSync(BACKUP_LOG_FILE);
    }
  } catch (_) {}
  try {
    if (fs.existsSync(LOG_FILE)) {
      const stat = fs.statSync(LOG_FILE);
      if (stat.size > MAX_LOG_SIZE) {
        fs.truncateSync(LOG_FILE, 0);
      } else {
        fs.renameSync(LOG_FILE, BACKUP_LOG_FILE);
      }
    }
  } catch (_) {}
}

function writeToFile(line) {
  try {
    let stat;
    try {
      stat = fs.statSync(LOG_FILE);
    } catch (e) {
      if (e.code !== "ENOENT") throw e;
    }
    if (stat && stat.size >= MAX_LOG_SIZE) {
      rotate();
    }
    fs.appendFileSync(LOG_FILE, line);
  } catch (err) {
    try {
      try {
        if (fs.existsSync(BACKUP_LOG_FILE)) fs.unlinkSync(BACKUP_LOG_FILE);
      } catch (_) {}
      try {
