{"cmd":"docker compose exec app node -e '
const { Queue, Worker } = require("bullmq");
const IORedis = require("ioredis");
const conn = new IORedis(process.env.REDIS_URL, { maxRetriesPerRequest: null });

(async () => {
  const testQueue = new Queue("test-limiter", { connection: conn });
  const start = Date.now();
  const timestamps = [];

  const worker = new Worker("test-limiter", async (job) => {
    timestamps.push(Date.now() - start);
  }, {
    connection: conn,
    concurrency: 5,
    limiter: {
      max: 5,
      duration: 1000,
    }
  });

  for (let i = 0; i < 10; i++) {
    await testQueue.add("test", { i });
  }

  await new Promise(r => setTimeout(r, 2500));
  console.log("Timestamps of 10 jobs processed:", timestamps);
  await worker.close();
  await testQueue.obliterate({ force: true });
  await conn.quit();
})();
'"}

{"cmd":"docker compose exec app node -e '
const { Queue, Worker } = require("bullmq");
const IORedis = require("ioredis");
const conn = new IORedis(process.env.REDIS_URL, { maxRetriesPerRequest: null });

(async () => {
  const testQueue = new Queue("test-backoff", { connection: conn });
  const delays = [];

  class CustomError extends Error {
    constructor(msg, retryAfter) {
      super(msg);
      this.retryAfter = retryAfter;
    }
  }

  const worker = new Worker("test-backoff", async (job) => {
    throw new CustomError("rate limited", 1500);
  }, {
    connection: conn,
    concurrency: 1,
    settings: {
      backoffStrategies: {
        custom(attemptsMade, type, err, job) {
          delays.push({ attemptsMade, type, err: err ? err.message : null, retryAfter: err ? err.retryAfter : null });
          return err && err.retryAfter ? err.retryAfter : 1000;
        }
      }
    }
  });

  await testQueue.add("test", {}, { attempts: 2, backoff: { type: "custom" } });
  await new Promise(r => setTimeout(r, 500));
  console.log("Recorded delays:", delays);
  await worker.close();
  await testQueue.obliterate({ force: true });
  await conn.quit();
})();
'"}

