      `<tr><td>${month}</td><td>${i}</td><td>${o ? o.sku : "-"}</td><td>${o ? o.amount_cents : 0}</td><td>${account.balance}</td></tr>`
    );
  }
  return `<table data-account="${account.id}">${lines.join("")}</table>`;
}

async function statementFor(accountId, asOf) {
  const month = monthOf(asOf);
  const key = `${accountId}:${month}`;
  if (cache.has(key)) {
    const val = cache.get(key);
    cache.delete(key);
    cache.set(key, val);
    return val;
  }
  const { rows: accounts } = await pool.query("SELECT id, balance FROM accounts WHERE id = $1", [accountId]);
  if (accounts.length === 0) return null;
  const { rows: orders } = await pool.query(
    "SELECT sku, amount_cents FROM orders WHERE account_id = $1 ORDER BY created_at DESC LIMIT 100",
    [accountId]
  );
  const html = render(accounts[0], orders, month);
  if (cache.size >= MAX_ENTRIES) {
    const oldest = cache.keys().next().value;
    cache.delete(oldest);
  }
  cache.set(key, html);
  return html;
}

async function test() {
  console.log("Start mem:", Math.round(process.memoryUsage().rss / 1024 / 1024), "MB");
  for (let i = 0; i < 1000; i++) {
    // Generate different months to force cache misses and evictions
    const fakeDate = new Date(2000, i % 120, 1).toISOString();
    await statementFor(1, fakeDate);
  }
  global.gc && global.gc();
  console.log("Mem after 1000 distinct calls with LRU 50:", Math.round(process.memoryUsage().rss / 1024 / 1024), "MB");
  console.log("Cache size:", cache.size);
  process.exit(0);
}
test();
'"}

