/bin/zsh -lc "docker compose exec app node -e '
async function retryDlq() {
  const { Queue } = require(\"bullmq\");
  const IORedis = require(\"ioredis\");
  const config = require(\"./src/config\");

  const connection = new IORedis(config.redisUrl, { maxRetriesPerRequest: null });
  const jobs = new Queue(\"jobs\", { connection });
  const deadLetters = new Queue(\"jobs-dlq\", { connection });

  const dlqJobs = await deadLetters.getJobs([\"waiting\", \"active\", \"delayed\", \"failed\", \"completed\"]);
  console.log(\"DLQ jobs found:\", dlqJobs.length);

  for (const job of dlqJobs) {
    const data = { ...job.data };
    delete data.error;
    console.log(\"Re-enqueuing job:\", job.name, job.id, data);
    await jobs.add(job.name, data, { attempts: 3, backoff: { type: \"fixed\", delay: 200 }, removeOnComplete: 5000, jobId: job.id });
    await job.remove();
  }

  await connection.quit();
  console.log(\"Done re-enqueuing DLQ jobs\");
}
retryDlq();
'"

