const { jobs, deadLetters } = require(\"./src/queue\");
async function run() {
  const failed = await jobs.getFailed();
  console.log(\"Failed jobs to retry:\", failed.length);
  for (const f of failed) {
    await f.retry();
  }
  console.log(\"All retried. Waiting for queue to clear...\");
  let pending = 1;
  while (pending > 0) {
    await new Promise(r => setTimeout(r, 500));
    const counts = await jobs.getJobCounts(\"waiting\", \"active\");
    pending = counts.waiting + counts.active;
    console.log(\"Pending:\", pending);
  }
  const dlqJobs = await deadLetters.getJobs([\"waiting\", \"active\", \"completed\", \"failed\", \"delayed\"]);
