{"cmd":"docker compose exec app node --experimental-websocket -e '
const ws = new WebSocket("ws://127.0.0.1:9229/f14b6f95-ef0c-4957-9d89-7c095692a9d8");
let step = 0;
ws.onopen = () => {
  ws.send(JSON.stringify({
    id: 1,
    method: "Runtime.evaluate",
    params: { expression: "process.mainModule.require(\"./services/statements\").statementFor" }
  }));
};
ws.onmessage = (msg) => {
  const d = JSON.parse(msg.data);
  step++;
  if (step === 1) {
    ws.send(JSON.stringify({
      id: 2,
      method: "Runtime.getProperties",
      params: { objectId: d.result.result.objectId }
    }));
  } else if (step === 2) {
    const scopesProp = d.result.internalProperties.find(p => p.name === "[[Scopes]]");
    ws.send(JSON.stringify({
      id: 3,
      method: "Runtime.getProperties",
      params: { objectId: scopesProp.value.objectId }
    }));
  } else if (step === 3) {
    const closureScope = d.result.result[0].value.objectId;
    ws.send(JSON.stringify({
      id: 4,
      method: "Runtime.getProperties",
      params: { objectId: closureScope }
    }));
  } else if (step === 4) {
    const cacheObj = d.result.result.find(p => p.name === "cache");
    ws.send(JSON.stringify({
      id: 5,
      method: "Runtime.getProperties",
      params: { objectId: cacheObj.value.objectId }
    }));
  } else if (step === 5) {
    console.log("Number of keys in cache:", d.result.result.length);
    console.log("Sample keys:", d.result.result.slice(0, 5).map(p => p.name));
    process.exit(0);
  }
};
'"}

