const { Queue, Worker } = require(\"bullmq\");
const IORedis = require(\"ioredis\");
const connection = new IORedis(\"redis://redis:6379\", { maxRetriesPerRequest: null });
const testQ = new Queue(\"test-manual-limiter\", { connection });
(async () => {
  await testQ.obliterate({ force: true });
  for (let i = 0; i < 10; i++) {
    await testQ.add(\"test\", { i }, { attempts: 3 });
  }
  let callCount = 0;
  const processed = [];
  const worker = new Worker(\"test-manual-limiter\", async (job) => {
    callCount++;
    console.log("'`Processing job ${job.data.i}, attemptsMade: ${job.attemptsMade}`);
    if (callCount > 3 && callCount < 7) {
      console.log(`Rate limiting job ${job.data.i}`);
      await worker.rateLimit(1000);
      throw Worker.RateLimitError();
    }
    processed.push(job.data.i);
  }, {
    connection,
    concurrency: 5
  });

  await new Promise(r => setTimeout(r, 2500));
  console.log("Processed:", processed);
  await worker.close();
  await connection.quit();
  process.exit(0);
})();
'"'"

