  await q.obliterate({ force: true }).catch(() => {});
  for (let i = 0; i < 20; i++) {
    await q.add("job", { i });
  }

  let startTime = Date.now();
  const completed = [];
  const worker = new Worker("test-manual-rate-limit-multi", async (job) => {
