{"cmd":"docker compose exec app node -e '
const { Queue, Worker } = require("bullmq");
const IORedis = require("ioredis");
const notifications = require("./src/services/notifications");
const { PartnerError } = require("./src/partner");

const connection = new IORedis("redis://redis:6379", { maxRetriesPerRequest: null });
const q = new Queue("test-actual-partner", { connection });

async function run() {
  await q.obliterate({ force: true }).catch(() => {});
  for (let i = 0; i < 20; i++) {
    await q.add("notification", { notificationId: "real-test-" + i, userId: 1, message: "hi" });
  }

  // Wait 1.5s to ensure partner rate limiter is completely fresh
  await new Promise(r => setTimeout(r, 1500));

  let completed = 0;
  let failed = 0;
  const worker = new Worker("test-actual-partner", async (job) => {
    try {
      await notifications.send(job.data);
      completed++;
    } catch (err) {
      if (err instanceof PartnerError && err.status === 429) {
        const delayMs = Math.max((err.retryAfterSec || 1) * 1000, 1000);
        await worker.rateLimit(delayMs);
        throw Worker.RateLimitError();
      }
      failed++;
      throw err;
    }
  }, { connection, concurrency: 5 });

  await new Promise(r => setTimeout(r, 6000));
  await worker.close();
  console.log("Completed:", completed, "Failed:", failed);
}
run();
'"}

