    req.on(\"upgrade\", (res, socket, head) => {
      let id = 1;
      function send(method, params) {
        const payload = Buffer.from(JSON.stringify({ id: id++, method, params }));
        const len = payload.length;
        let header;
        if (len < 126) header = Buffer.from([0x81, 0x80 | len, 0, 0, 0, 0]);
        else if (len < 65536) {
