        const text = d.toString();
        const match = text.match(/\{.*\}/s);
        if (!match) return;
        const msg = JSON.parse(match[0]);
        if (msg.id === 1) {
          send("Runtime.getProperties", { objectId: msg.result.result.objectId });
        } else if (msg.id === 2) {
          const scopes = msg.result.internalProperties.find(p => p.name === "[[Scopes]]");
          send("Runtime.getProperties", { objectId: scopes.value.objectId });
        } else if (msg.id === 3) {
          // get closure scope object
          const closure = msg.result.result.find(p => p.value.description.startsWith("Closure"));
          send("Runtime.getProperties", { objectId: closure.value.objectId });
        } else if (msg.id === 4) {
          const cacheProp = msg.result.result.find(p => p.name === "cache");
          send("Runtime.getProperties", { objectId: cacheProp.value.objectId });
        } else if (msg.id === 5) {
          console.log("Cache key count:", msg.result.result.length);
          console.log("Sample keys:", msg.result.result.slice(0, 10).map(p => p.name));
          process.exit(0);
        }
      });
    });
    req.end();
  });
});
'"}

