/bin/zsh -lc "cat << 'EOF' > src/logger.js
const fs = require(\"fs\");
const path = require(\"path\");
const config = require(\"./config\");

const LEVELS = { debug: 10, info: 20, warn: 30, error: 40 };
const threshold = LEVELS[config.logLevel] || LEVELS.info;
const LOG_FILE = path.join(config.logDir, \"app.log\");
const MAX_LOG_SIZE = 128 * 1024; // 128 KB
const BACKUP_FILE = path.join(config.logDir, \"app.log.1\");

try {
  fs.mkdirSync(config.logDir, { recursive: true });
} catch (e) {
  // Ignore directory creation errors
}

function rotateIfNeeded() {
  try {
    const stats = fs.statSync(LOG_FILE);
    if (stats.size >= MAX_LOG_SIZE) {
      try {
        if (fs.existsSync(BACKUP_FILE)) {
          fs.unlinkSync(BACKUP_FILE);
        }
      } catch (e) {
        // Ignore backup unlink error
      }
      fs.renameSync(LOG_FILE, BACKUP_FILE);
    }
  } catch (e) {
    // If file doesn't exist or stat fails, ignore
  }
}

function write(level, msg, fields = {}) {
  if (LEVELS[level] < threshold) return;
  const line = JSON.stringify({ ts: new Date().toISOString(), level, msg, ...fields }) + \"\\n\";
  try {
    rotateIfNeeded();
    fs.appendFileSync(LOG_FILE, line);
  } catch (err) {
    // If disk is full or writing fails, avoid throwing to prevent job crashes
  }
  if (level "'!== "debug") {
    try {
      process.stdout.write(line);
    } catch (e) {
      // Ignore stdout write errors
    }
  }
}

module.exports = {
  debug: (msg, fields) => write("debug", msg, fields),
  info: (msg, fields) => write("info", msg, fields),
  warn: (msg, fields) => write("warn", msg, fields),
  error: (msg, fields) => write("error", msg, fields),
};
EOF
'

